#!/usr/bin/env node
// Helpers for the per-platform npm packages of @godspeedai/domainforge.
//
// Platform package manifests (domainforge-typescript/npm/<platform>/package.json)
// are generated by `napi create-npm-dirs` from the napi.targets list and the
// main package version, so they never need a separate version bump.
//
//   stage            copy the .node built on this host into its platform dir
//   inject-optional  add optionalDependencies (same version) to the main package.json
//   verify-main      fail if the packed main tarball ships a .node or lacks optionalDependencies
//   smoke            install platform + main tarballs into a clean dir and call the API
import { execFileSync } from 'node:child_process'
import { copyFileSync, mkdtempSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'

const pkgDir = resolve(process.env.DF_TS_DIR ?? 'domainforge-typescript')
const readJson = (p) => JSON.parse(readFileSync(p, 'utf8'))
const mainPkgPath = join(pkgDir, 'package.json')
const npmDir = join(pkgDir, 'npm')

function platforms() {
  return readdirSync(npmDir)
    .map((d) => ({ dir: join(npmDir, d), pkg: readJson(join(npmDir, d, 'package.json')) }))
    .sort((a, b) => a.pkg.name.localeCompare(b.pkg.name))
}

function fail(msg) {
  console.error(`ERROR: ${msg}`)
  process.exit(1)
}

const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm'
const run = (cmd, args, opts = {}) =>
  execFileSync(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32', ...opts })

const commands = {
  stage() {
    const nodes = readdirSync(pkgDir).filter((f) => /^domainforge-core\..+\.node$/.test(f))
    if (nodes.length !== 1) fail(`expected exactly one built .node in ${pkgDir}, found: ${nodes.join(', ') || 'none'}`)
    const target = platforms().find((p) => p.pkg.main === nodes[0])
    if (!target) fail(`no npm/<platform> package declares main ${nodes[0]}; is the target in napi.targets?`)
    copyFileSync(join(pkgDir, nodes[0]), join(target.dir, nodes[0]))
    console.log(target.dir.replaceAll('\\', '/'))
  },

  'inject-optional'() {
    const main = readJson(mainPkgPath)
    main.optionalDependencies = {}
    for (const { pkg } of platforms()) {
      if (pkg.version !== main.version) fail(`${pkg.name} is ${pkg.version}, main is ${main.version}`)
      main.optionalDependencies[pkg.name] = main.version
    }
    writeFileSync(mainPkgPath, JSON.stringify(main, null, 2) + '\n')
    console.log(main.optionalDependencies)
  },

  'verify-main'(tgz) {
    const listing = execFileSync('tar', ['-tzf', tgz], { encoding: 'utf8' })
    if (/\.node$/m.test(listing)) fail('main tarball must not contain a .node binary')
    for (const f of ['package/index.js', 'package/index.d.ts']) {
      if (!listing.includes(f)) fail(`main tarball is missing ${f}`)
    }
    const manifest = execFileSync('tar', ['-xzOf', tgz, 'package/package.json'], { encoding: 'utf8' })
    const main = JSON.parse(manifest)
    const expected = platforms().map((p) => p.pkg.name)
    for (const name of expected) {
      if (main.optionalDependencies?.[name] !== main.version) fail(`optionalDependencies.${name} != ${main.version}`)
    }
    console.log(`main tarball ok (${expected.length} optional platform packages)`)
  },

  smoke(platformTgz, mainTgz) {
    const main = readJson(mainPkgPath)
    const platformName = execFileSync('tar', ['-xzOf', platformTgz, 'package/package.json'], { encoding: 'utf8' })
    const platformPkg = JSON.parse(platformName).name
    const dir = mkdtempSync(join(tmpdir(), 'df-smoke-'))
    writeFileSync(join(dir, 'package.json'), JSON.stringify({ name: 'df-smoke', version: '0.0.0', private: true }))
    // Install the platform tarball first so the main package's optional
    // dependency (not yet on the registry in CI) is already satisfied.
    run(npm, ['install', '--ignore-scripts', '--no-audit', '--no-fund', resolve(platformTgz), resolve(mainTgz)], { cwd: dir })
    const probe = `
      const assert = require('node:assert')
      const path = require('node:path')
      const platformPkg = ${JSON.stringify(platformPkg)}
      const mainDir = path.dirname(require.resolve('@godspeedai/domainforge/package.json'))
      assert(!require('node:fs').readdirSync(mainDir).some((f) => f.endsWith('.node')), 'main package must not carry a .node')
      const platformDir = path.dirname(require.resolve(platformPkg + '/package.json'))
      const df = require('@godspeedai/domainforge')
      const graph = df.Graph.parse('Entity "Warehouse"\\nEntity "Factory"')
      assert.strictEqual(graph.entityCount(), 2)
      assert.strictEqual(df.checkFormat('Entity "Warehouse"\\n'), true)
      console.log('smoke ok', process.platform, process.arch, platformPkg, ${JSON.stringify(main.version)}, platformDir)
    `
    run(process.execPath, ['-e', probe], { cwd: dir, shell: false })
  },
}

const [cmd, ...args] = process.argv.slice(2)
if (!commands[cmd]) fail(`usage: npm_platform_packages.mjs <${Object.keys(commands).join('|')}> [args]`)
commands[cmd](...args)
